    ('D001', 'build_next', 'computer systems and programming', 'Build this next because the checked domain evidence names it as part of Software Engineering work and preparation.', 'Named domain-level Nigerian evidence (skill); it is a guidance starting point, not a universal checklist.', 'https://esco.ec.europa.eu/en/use-esco', 4, '{"source": "nigerian_web_source_evidence", "domain_id": "D001", "evidence_kind": "skill", "guidance_layer": "global_domain_foundation_v1", "ownership": "domain_owned"}'),
    ('D001', 'build_next', 'software packages', 'Build this next because the checked domain evidence names it as part of Software Engineering work and preparation.', 'Named domain-level Nigerian evidence (skill); it is a guidance starting point, not a universal checklist.', 'https://esco.ec.europa.eu/en/use-esco', 5, '{"source": "nigerian_web_source_evidence", "domain_id": "D001", "evidence_kind": "skill", "guidance_layer": "global_domain_foundation_v1", "ownership": "domain_owned"}'),
