    ('D004', 'build_next', 'design and query databases', 'Build this next because the checked domain evidence names it as part of Cybersecurity work and preparation.', 'Named domain-level Nigerian evidence (competency); it is a guidance starting point, not a universal checklist.', 'https://esco.ec.europa.eu/en/use-esco', 3, '{"source": "nigerian_web_source_evidence", "domain_id": "D004", "evidence_kind": "competency", "guidance_layer": "global_domain_foundation_v1", "ownership": "domain_owned"}'),
    ('D004', 'build_next', 'computer systems and programming', 'Build this next because the checked domain evidence names it as part of Cybersecurity work and preparation.', 'Named domain-level Nigerian evidence (skill); it is a guidance starting point, not a universal checklist.', 'https://esco.ec.europa.eu/en/use-esco', 4, '{"source": "nigerian_web_source_evidence", "domain_id": "D004", "evidence_kind": "skill", "guidance_layer": "global_domain_foundation_v1", "ownership": "domain_owned"}'),
    ('D004', 'build_next', 'software packages', 'Build this next because the checked domain evidence names it as part of Cybersecurity work and preparation.', 'Named domain-level Nigerian evidence (skill); it is a guidance starting point, not a universal checklist.', 'https://esco.ec.europa.eu/en/use-esco', 5, '{"source": "nigerian_web_source_evidence", "domain_id": "D004", "evidence_kind": "skill", "guidance_layer": "global_domain_foundation_v1", "ownership": "domain_owned"}'),
    ('D004', 'build_next', 'Understand computer programming', 'Build this after the orientation because strong CCMAS curriculum anchors show the concept is taught in programmes mapped to this domain.', 'CCMAS curriculum anchors: Computing::Cybersecurity / Computer Programming I; Computing::Cybersecurity / Computer Programming II; Computing::Information and Communication Technology / Computer Programming I; Computing::Information and Communication Technology / Computer Programming II', 'https://esco.ec.europa.eu/en/use-esco', 6, '{"source": "ccmas_programme_domain_evidence", "domain_id": "D004", "anchor": "computer programming", "guidance_layer": "global_domain_foundation_v1", "ownership": "domain_owned"}'),
