    ('D146', 'build_next', 'Understand thermodynamics', 'Build this after the orientation because strong CCMAS curriculum anchors show the concept is taught in programmes mapped to this domain.', 'CCMAS curriculum anchors: Engineering::CIVIL ENGINEERING / General Physics III; Engineering::CIVIL ENGINEERING / Fundamentals of Thermodynamics; Engineering::CIVIL ENGINEERING / Project; Engineering::ELECTRICAL ENGINEERING / General Physics III', 'https://esco.ec.europa.eu/en/use-esco', 6, '{"source": "ccmas_programme_domain_evidence", "domain_id": "D146", "anchor": "thermodynamics", "guidance_layer": "global_domain_foundation_v1", "ownership": "domain_owned"}'),
    ('D146', 'build_next', 'Understand electrical engineering', 'Build this after the orientation because strong CCMAS curriculum anchors show the concept is taught in programmes mapped to this domain.', 'CCMAS curriculum anchors: Engineering::ELECTRICAL ENGINEERING / Introduction to Electrical Engineering; Engineering::ELECTRICAL ENGINEERING / Electrical Engineering Materials; Engineering::ELECTRICAL ENGINEERING / Software/Computer Applications in Electrical Engineering; Engineering::ELECTRICAL ENGINEERING / Energy Economy', 'https://esco.ec.europa.eu/en/use-esco', 7, '{"source": "ccmas_programme_domain_evidence", "domain_id": "D146", "anchor": "electrical engineering", "guidance_layer": "global_domain_foundation_v1", "ownership": "domain_owned"}'),
