    ('D076', 'build_next', 'complete sea time and approved training', 'Build this next because the checked domain evidence names it as part of Maritime work and preparation.', 'Named domain-level Nigerian evidence (competency); it is a guidance starting point, not a universal checklist.', 'https://esco.ec.europa.eu/en/use-esco', 3, '{"source": "nigerian_web_source_evidence", "domain_id": "D076", "evidence_kind": "competency", "guidance_layer": "global_domain_foundation_v1", "ownership": "domain_owned"}'),
