    ('D076', 'build_next', 'Understand ship', 'Build this after the orientation because strong CCMAS curriculum anchors show the concept is taught in programmes mapped to this domain.', 'CCMAS curriculum anchors: Architecture::Naval Architecture / Introduction to Naval Architecture; Architecture::Naval Architecture / Fluid Mechanics, Hydrostatics and Stability; Architecture::Naval Architecture / Ship Design and Drawing I; Architecture::Naval Architecture / Ship Design and Drawing II', 'https://esco.ec.europa.eu/en/use-esco', 6, '{"source": "ccmas_programme_domain_evidence", "domain_id": "D076", "anchor": "ship", "guidance_layer": "global_domain_foundation_v1", "ownership": "domain_owned"}'),
    ('D076', 'build_next', 'Understand marine', 'Build this after the orientation because strong CCMAS curriculum anchors show the concept is taught in programmes mapped to this domain.', 'CCMAS curriculum anchors: Architecture::Naval Architecture / Introduction to Naval Architecture; Architecture::Naval Architecture / Fluid Mechanics, Hydrostatics and Stability; Architecture::Naval Architecture / Engineering Applications for Naval Architects; Architecture::Naval Architecture / Marine Engines and Fuels', 'https://esco.ec.europa.eu/en/use-esco', 7, '{"source": "ccmas_programme_domain_evidence", "domain_id": "D076", "anchor": "marine", "guidance_layer": "global_domain_foundation_v1", "ownership": "domain_owned"}'),
