    ('D149', 'build_next', 'Understand international relations', 'Build this after the orientation because strong CCMAS curriculum anchors show the concept is taught in programmes mapped to this domain.', 'CCMAS curriculum anchors: Education::Political Science / Introduction to International Relations; Social Sciences::International Relations / Theories of International Relations; Social Sciences::International Relations / Foreign Policies of the Powers; Social Sciences::International Relations / Research Project', 'https://esco.ec.europa.eu/en/use-esco', 6, '{"source": "ccmas_programme_domain_evidence", "domain_id": "D149", "anchor": "international relations", "guidance_layer": "global_domain_foundation_v1", "ownership": "domain_owned"}'),
