    ('D109', 'build_next', 'Understand metallurgical', 'Build this after the orientation because strong CCMAS curriculum anchors show the concept is taught in programmes mapped to this domain.', 'CCMAS curriculum anchors: Engineering::MATERIALS AND METALLURGICAL ENGINEERING / Introduction to Materials and Metallurgical Engineering; Engineering::MATERIALS AND METALLURGICAL ENGINEERING / Engineering Materials; Engineering::MATERIALS AND METALLURGICAL ENGINEERING / Thermodynamics of Materials; Engineering::MATERIALS AND METALLURGICAL ENGINEERING / Physical Metallurgy I', 'https://esco.ec.europa.eu/en/use-esco', 6, '{"source": "ccmas_programme_domain_evidence", "domain_id": "D109", "anchor": "metallurgical", "guidance_layer": "global_domain_foundation_v1", "ownership": "domain_owned"}'),
    ('D109', 'build_next', 'Understand dies', 'Build this after the orientation because strong CCMAS curriculum anchors show the concept is taught in programmes mapped to this domain.', 'CCMAS curriculum anchors: Allied Health Sciences::Dental Technology / Dental Laboratory Techniques I; Allied Health Sciences::Dental Technology / Fixed Prosthodontics and technique I; Engineering::MATERIALS AND METALLURGICAL ENGINEERING / Engineer in Society; Engineering::MATERIALS AND METALLURGICAL ENGINEERING / General Practical Physics I', 'https://esco.ec.europa.eu/en/use-esco', 7, '{"source": "ccmas_programme_domain_evidence", "domain_id": "D109", "anchor": "dies", "guidance_layer": "global_domain_foundation_v1", "ownership": "domain_owned"}'),
    ('D109', 'choose_area', 'Compare the areas inside this domain', 'Choose an area after understanding the shared foundation; each area adds a different set of methods, capabilities and roles.', 'Current subgroup records: Stationary Plant and Machine Operators.', NULL, 8, '{"source": "domain_structure", "domain_id": "D109", "subgroup_count": 1, "guidance_layer": "global_domain_foundation_v1", "ownership": "domain_owned"}'),
    ('D110', 'start_here', 'Understand Chemical, Rubber', 'Start here because the domain definition explains the field before a student chooses a specialised area or role.', 'Domain definition: Chemical and rubber processing involves running plants that convert raw materials into products such as soap, lime and other chemicals. Operators control distillation units, kilns, blenders and soap-making machines, adjust process settings, troubleshoot faults and follow strict safety rules with protective equipment. Common employers are chemical plants, soap factories and other process industries.', 'https://esco.ec.europa.eu/en/use-esco', 1, '{"source": "domain_definition_library_and_domain_meta", "domain_id": "D110", "guidance_layer": "global_domain_foundation_v1", "ownership": "domain_owned"}'),
    ('D110', 'build_next', 'engineering safety and reliability', 'Build this next because the checked domain evidence names it as part of Chemical, Rubber work and preparation.', 'Named domain-level Nigerian evidence (competency); it is a guidance starting point, not a universal checklist.', 'https://esco.ec.europa.eu/en/use-esco', 2, '{"source": "nigerian_web_source_evidence", "domain_id": "D110", "evidence_kind": "competency", "guidance_layer": "global_domain_foundation_v1", "ownership": "domain_owned"}'),
