    ('D110', 'build_next', 'Understand petrochemical', 'Build this after the orientation because strong CCMAS curriculum anchors show the concept is taught in programmes mapped to this domain.', 'CCMAS curriculum anchors: Engineering::NATURAL GAS ENGINEERING / Natural Gas Utilisation and Monetisation Concepts; Engineering::PETROCHEMICAL ENGINEERING / Introduction to - Petrochemical Engineering 2 C 30; Engineering::PETROCHEMICAL ENGINEERING / Introduction to petro- chemical engineering calculations; Engineering::PETROCHEMICAL ENGINEERING / Chemical Reaction Kinetics and catalysis', 'https://esco.ec.europa.eu/en/use-esco', 6, '{"source": "ccmas_programme_domain_evidence", "domain_id": "D110", "anchor": "petrochemical", "guidance_layer": "global_domain_foundation_v1", "ownership": "domain_owned"}'),
    ('D110', 'build_next', 'Understand chemical engineering', 'Build this after the orientation because strong CCMAS curriculum anchors show the concept is taught in programmes mapped to this domain.', 'CCMAS curriculum anchors: Engineering::CHEMICAL ENGINEERING / Introduction to Chemical Engineering; Engineering::CHEMICAL ENGINEERING / Chemical Engineering Fundamentals; Engineering::CHEMICAL ENGINEERING / Statistics for Chemical Engineers; Engineering::CHEMICAL ENGINEERING / Chemical Engineering Thermodynamics', 'https://esco.ec.europa.eu/en/use-esco', 7, '{"source": "ccmas_programme_domain_evidence", "domain_id": "D110", "anchor": "chemical engineering", "guidance_layer": "global_domain_foundation_v1", "ownership": "domain_owned"}'),
