    ('D111', 'build_next', 'Understand garment', 'Build this after the orientation because strong CCMAS curriculum anchors show the concept is taught in programmes mapped to this domain.', 'CCMAS curriculum anchors: Environmental Sciences::Clothing and Textile Design / Clothing Construction; Environmental Sciences::Clothing and Textile Design / Computer Aided Design in Clothing and Textile; Environmental Sciences::Clothing and Textile Design / Fashion Drawing, Design and Modelling; Environmental Sciences::Fashion design / Fashion Design /Illustration I', 'https://esco.ec.europa.eu/en/use-esco', 6, '{"source": "ccmas_programme_domain_evidence", "domain_id": "D111", "anchor": "garment", "guidance_layer": "global_domain_foundation_v1", "ownership": "domain_owned"}'),
    ('D111', 'build_next', 'Understand textile', 'Build this after the orientation because strong CCMAS curriculum anchors show the concept is taught in programmes mapped to this domain.', 'CCMAS curriculum anchors: Environmental Sciences::Clothing and Textile Design / Introduction to weaving Techniques; Environmental Sciences::Clothing and Textile Design / Basic Design in Textile Production; Environmental Sciences::Clothing and Textile Design / Textile Materials; Environmental Sciences::Clothing and Textile Design / Creative Fabrics and Fashion Accessories', 'https://esco.ec.europa.eu/en/use-esco', 7, '{"source": "ccmas_programme_domain_evidence", "domain_id": "D111", "anchor": "textile", "guidance_layer": "global_domain_foundation_v1", "ownership": "domain_owned"}'),
