    ('D070', 'build_next', 'work across production and distribution', 'Build this next because the checked domain evidence names it as part of Performing Arts & Entertainment work and preparation.', 'Named domain-level Nigerian evidence (competency); it is a guidance starting point, not a universal checklist.', 'https://esco.ec.europa.eu/en/use-esco', 3, '{"source": "nigerian_web_source_evidence", "domain_id": "D070", "evidence_kind": "competency", "guidance_layer": "global_domain_foundation_v1", "ownership": "domain_owned"}'),
    ('D070', 'build_next', 'creative production', 'Build this next because the checked domain evidence names it as part of Performing Arts & Entertainment work and preparation.', 'Named domain-level Nigerian evidence (skill); it is a guidance starting point, not a universal checklist.', 'https://esco.ec.europa.eu/en/use-esco', 4, '{"source": "nigerian_web_source_evidence", "domain_id": "D070", "evidence_kind": "skill", "guidance_layer": "global_domain_foundation_v1", "ownership": "domain_owned"}'),
    ('D070', 'build_next', 'entertainment operations', 'Build this next because the checked domain evidence names it as part of Performing Arts & Entertainment work and preparation.', 'Named domain-level Nigerian evidence (skill); it is a guidance starting point, not a universal checklist.', 'https://esco.ec.europa.eu/en/use-esco', 5, '{"source": "nigerian_web_source_evidence", "domain_id": "D070", "evidence_kind": "skill", "guidance_layer": "global_domain_foundation_v1", "ownership": "domain_owned"}'),
    ('D070', 'build_next', 'Understand production design', 'Build this after the orientation because strong CCMAS curriculum anchors show the concept is taught in programmes mapped to this domain.', 'CCMAS curriculum anchors: Arts::Film Production / Principles & Pracice Of Screenwriting, Direction & Production Design I (2; Arts::Film Production / Principles & Practice Of Screenwriting, Direction & Production Design II; Arts::Film Production / Principles & Practice of Screenwriting, Direction & Production Design III; Arts::Film Production / Principles & Practice Of Screenwriting, Direction & Production Design IV', 'https://esco.ec.europa.eu/en/use-esco', 6, '{"source": "ccmas_programme_domain_evidence", "domain_id": "D070", "anchor": "production design", "guidance_layer": "global_domain_foundation_v1", "ownership": "domain_owned"}'),
    ('D070', 'build_next', 'Understand rehearsal', 'Build this after the orientation because strong CCMAS curriculum anchors show the concept is taught in programmes mapped to this domain.', 'CCMAS curriculum anchors: Arts::Theatre Arts / Participation Orientation/Workshop Productions; Arts::Theatre Arts / Community Theatre; Arts::Theatre Arts / Educational Drama and Theatre:; Education::Creative Arts Education / Introduction to Directing', 'https://esco.ec.europa.eu/en/use-esco', 7, '{"source": "ccmas_programme_domain_evidence", "domain_id": "D070", "anchor": "rehearsal", "guidance_layer": "global_domain_foundation_v1", "ownership": "domain_owned"}'),
